---@class TriggerGiftActivityConfig
local TriggerGiftActivityConfig = T(Global, "TriggerGiftActivityConfig")
---@type TriggerGiftDescConfigData[]
local Settings = {}

function TriggerGiftActivityConfig:init()
    local config = FileUtil.getConfigFromCsv("common/TriggerGiftActivity.csv", 2, true, true)
    for _, item in pairs(config) do
        -- index	activityId	startDate	endDate
        local startTime = nil
        local endTime = nil
        if item.startDate ~= "#" then
            local _, _, year, month, day, hour, min, sec = string.find(item.startDate, "(%d+)-(%d+)-(%d+)-(%d+)-(%d+)-(%d+)")
            startTime = DateUtil.date2BeiJingTime({ year = year, month = month, day = day, hour = hour, min = min, sec = sec })
        end
        if item.endDate ~= "#" then
            local _, _, year, month, day, hour, min, sec = string.find(item.endDate, "(%d+)-(%d+)-(%d+)-(%d+)-(%d+)-(%d+)")
            endTime = DateUtil.date2BeiJingTime({ year = year, month = month, day = day, hour = hour, min = min, sec = sec })
        end
        ---@class TriggerGiftActivityConfigData
        local data = {
            index = item.index,
            activityId = tonumber(item.activityId),
            startDate = startTime,
            endDate = endTime
        }
        Settings[data.activityId] = data
    end
end

---@return TriggerGiftActivityConfigData[]
function TriggerGiftActivityConfig:getAllCfg()
    return Settings
end

---@return TriggerGiftDescConfigData
function TriggerGiftActivityConfig:getCfgById(id)
    return Settings[id]
end

TriggerGiftActivityConfig:init()

return TriggerGiftActivityConfig